// 检查数字是否溢出
static bool adddgt(unsigned long *u, unsigned long d, int base)
{
    // 检查添加新数字后是否会导致整数溢出
    if (*u > (ULONG_MAX - d) / base) {   // 等效于 *u * base + d > ULONG_MAX
        return false;
    }
    *u = (*u) * base + d;
    return true;
}

