// 查找与')'匹配的'('的索引
int find_matching_paren(int start_index) {
    if (start_index <= 0) {
        return -1;
    }
    int nest_level = 1; // 从 start_index 是 ')'，所以初始嵌套为1
    for (int i = start_index - 1; i >= 0; i--) {
        if (Index[i] == 41) { // ')'
            nest_level++;
        } else if (Index[i] == 40) { // '('
            nest_level--;
            if (nest_level == 0) {
                return i;
            }
        }
    }
    return -1; // 没有找到匹配
}


